// "The evidence" view: what happened when the recommendations were tested on
// real datasets. Generated by bench/dcn/evidence.py from the committed run in
// bench/results/, so nothing here is typed by hand or rounded in the site's
// favour.

import { esc } from './html.js';

const pct = (x) => `${Math.round(x * 100)}%`;
const num = (x, digits = 3) => (x == null || Number.isNaN(x) ? '—' : x.toFixed(digits));

// A model's line for one task, or null when the benchmark never ran it there.
export function evidenceFor(T, code, task) {
  const model = T.EVIDENCE?.models?.[code];
  const benchTask = task === 'category' ? 'classification' : task === 'number' ? 'regression' : null;
  if (!model || !benchTask) return null;
  return model.tasks[benchTask] ? { ...model.tasks[benchTask], task: benchTask } : null;
}

// One sentence for a recommendation card.
export function evidenceSentence(entry) {
  if (!entry) return '';
  const { datasets, was_best: best, median_regret: regret, task } = entry;
  const beaten = best === 0
    ? 'was never the best choice'
    : `was the best choice ${best} ${best === 1 ? 'time' : 'times'}`;
  return `On ${datasets} ${task} datasets it ${beaten}, and typically landed ${num(regret)} below the best model that ran.`;
}

function headlineTable(headline) {
  const tasks = Object.keys(headline);
  const rows = [
    ['the first model shown', 'first', 'first_was_best'],
    ['best of the four shown', 'top4', 'top4_was_best'],
    ['always use boosting', 'boosting', 'boosting_was_best'],
    ['a model picked at random from the eligible ones', 'random_eligible', null],
  ];
  return `<table class="ev-table">
    <thead><tr><th>median regret</th>${tasks.map(t =>
      `<th>${esc(t)}<span class="ev-sub">${esc(headline[t].metric)}, ${unitsLabel(headline[t])}</span></th>`).join('')}</tr></thead>
    <tbody>${rows.map(([label, key, bestKey]) => `<tr>
      <td>${esc(label)}</td>
      ${tasks.map(t => `<td>${num(headline[t][key])}${bestKey
        ? `<span class="ev-sub">best ${pct(headline[t][bestKey])} of the time</span>` : ''}</td>`).join('')}
    </tr>`).join('')}</tbody>
  </table>`;
}

// A p-value as a reader should see it: small ones in scientific notation
// rather than rounded to a reassuring zero.
export function formatP(p) {
  if (p == null || Number.isNaN(p)) return '—';
  if (p < 0.001) return p.toExponential(1).replace('e-', ' × 10⁻').replace(/⁻(\d+)/, (_, d) =>
    '⁻' + [...d].map(c => '⁰¹²³⁴⁵⁶⁷⁸⁹'[c]).join(''));
  return p < 0.1 ? p.toFixed(3) : p.toFixed(2);
}

// Is a difference more than luck? The threshold is the usual 5%, after Holm's
// correction for testing the order in use against several alternatives.
export const ALPHA = 0.05;
export const beyondLuck = (test) => test != null && test.p_holm != null && test.p_holm < ALPHA;

// Under 5% but not under 1% is past the line, but not by much, and should read that way.
export function luckWords(test) {
  if (!beyondLuck(test)) return 'within what luck produces';
  return test.p_holm < 0.01 ? 'more than luck' : 'more than luck, narrowly';
}

const STRATEGY_KEYS = ['current', 'prior', 'prior_fit', 'prior_knn', 'boosting', 'tuned', 'tabpfn'];

// The references: what the order in use is compared with, beyond counting coordinates.
const REFERENCE_KEYS = ['boosting', 'tuned', 'tabpfn'];

// "classification datasets", or "independent regression units" when synthetic
// families were counted once, so a count always says what it counts.
export function unitNoun(entry, task) {
  return (entry?.units ?? entry?.datasets) < entry?.datasets ? `independent ${task} units` : `${task} datasets`;
}

// "101 datasets, 35 independent" when synthetic families were counted once.
export function unitsLabel(entry) {
  const units = entry.units ?? entry.datasets;
  return units < entry.datasets ? `${entry.datasets} datasets, ${units} independent` : `${entry.datasets} datasets`;
}

function strategyLabel(ranking, key) {
  for (const task of Object.keys(ranking.tasks)) {
    const s = ranking.tasks[task].strategies[key];
    if (s) return s.label;
  }
  return key;
}

// How the order the site now uses compares with what it used to do, and with
// reaching for boosting. Every number is leave-one-dataset-out: the dataset
// being ranked never contributed to the weights that rank it. The interval
// under each median is what resampling the datasets does to it.
function rankingTable(ranking) {
  if (!ranking) return '';
  const tasks = Object.keys(ranking.tasks);
  const chosenNote = (key) => (key === ranking.chosen ? ' <span class="ev-chosen">in use</span>' : '');
  return `<table class="ev-table">
    <thead><tr><th>median regret, leave-one-dataset-out</th>${tasks.map(t =>
      `<th>${esc(t)}<span class="ev-sub">${esc(ranking.tasks[t].metric)}, ${unitsLabel(ranking.tasks[t])}</span></th>`).join('')}</tr></thead>
    <tbody>${STRATEGY_KEYS.map(key => `<tr>
      <td>${esc(strategyLabel(ranking, key))}${chosenNote(key)}</td>
      ${tasks.map(t => { const s = ranking.tasks[t].strategies[key];
        if (!s) return '<td>—</td>';
        const ci = s.ci && s.ci[0] != null ? `<span class="ev-sub">95% interval ${num(s.ci[0])} to ${num(s.ci[1])}</span>` : '';
        return `<td>${num(s.median_regret)}${ci}<span class="ev-sub">best ${pct(s.was_best)} of the time</span>${
          subsetNote(s.units, ranking.tasks[t])}</td>`;
      }).join('')}
    </tr>`).join('')}</tbody>
  </table>`;
}

// A reference that skipped datasets (TabPFN has a row limit) is judged only on
// the ones it ran on, and the cell says so.
export function subsetNote(units, entry) {
  const all = entry?.units ?? entry?.datasets;
  return units != null && all != null && units < all
    ? `<span class="ev-sub">only the ${units} it ran on</span>` : '';
}

// How far each strategy lands from the best of everything that ran, the
// references included: what is left on the table.
function ceilingTable(ranking) {
  const tasks = Object.keys(ranking?.tasks ?? {}).filter(t => ranking.tasks[t].ceiling);
  if (!tasks.length) return '';
  const keys = STRATEGY_KEYS.filter(k => tasks.some(t => ranking.tasks[t].ceiling[k]));
  const chosenNote = (key) => (key === ranking.chosen ? ' <span class="ev-chosen">in use</span>' : '');
  return `<table class="ev-table">
    <thead><tr><th>median gap to the best of everything</th>${tasks.map(t =>
      `<th>${esc(t)}<span class="ev-sub">${esc(ranking.tasks[t].metric)}, ${unitsLabel(ranking.tasks[t])}</span></th>`).join('')}</tr></thead>
    <tbody>${keys.map(key => `<tr>
      <td>${esc(strategyLabel(ranking, key))}${chosenNote(key)}</td>
      ${tasks.map(t => { const c = ranking.tasks[t].ceiling[key];
        if (!c) return '<td>—</td>';
        return `<td>${num(c.median_gap)}<span class="ev-sub">95% interval ${num(c.ci[0])} to ${num(c.ci[1])}</span>
          <span class="ev-sub">the best of everything ${pct(c.at_ceiling)} of the time</span>${subsetNote(c.units, ranking.tasks[t])}</td>`;
      }).join('')}
    </tr>`).join('')}</tbody>
  </table>`;
}

// One sentence per reference: is the order in use better than always using it?
export function referenceVerdict(ranking, key, what) {
  if (!ranking?.chosen || ranking.chosen === key) return '';
  const parts = [], beyond = [], narrow = [];
  for (const [task, entry] of Object.entries(ranking.tasks)) {
    const c = entry.against_chosen?.[key];
    if (!c) continue;
    const unit = unitNoun({ datasets: entry.datasets, units: entry.units }, task);
    parts.push(`${c.wins} of ${c.wins + c.losses + c.ties} ${unit} (p = ${formatP(c.p_holm)})`);
    if (beyondLuck(c)) {
      beyond.push(`${task} ${c.wins > c.losses ? 'win' : 'loss'}`);
      if (c.p_holm >= 0.01) narrow.push(task);
    }
  }
  if (!parts.length) return '';
  const verdict = beyond.length === 0
    ? (parts.length > 1 ? 'Neither difference is more than luck.' : 'That is within what luck produces.')
    : `More than luck: the ${beyond.join(' and the ')}${narrow.length ? ', narrowly' : ''}.`;
  return `Against ${what}, the order in use was better on ${parts.join(' and ')}. ${verdict}`;
}

// The order in use against each alternative, dataset by dataset.
function comparisonTable(ranking) {
  if (!ranking?.chosen) return '';
  const tasks = Object.keys(ranking.tasks).filter(t => ranking.tasks[t].against_chosen);
  const others = STRATEGY_KEYS.filter(k => k !== ranking.chosen &&
    tasks.some(t => ranking.tasks[t].against_chosen[k]));
  if (!tasks.length || !others.length) return '';
  return `<table class="ev-table">
    <thead><tr><th>the order in use, against</th>${tasks.map(t => `<th>${esc(t)}</th>`).join('')}</tr></thead>
    <tbody>${others.map(key => `<tr>
      <td>${esc(strategyLabel(ranking, key))}</td>
      ${tasks.map(t => { const c = ranking.tasks[t].against_chosen[key];
        if (!c) return '<td>—</td>';
        return `<td>better on ${c.wins}, worse on ${c.losses}${c.ties ? `, tied on ${c.ties}` : ''}
          <span class="ev-sub">p = ${formatP(c.p_holm)}, ${luckWords(c)}</span>${subsetNote(c.units, ranking.tasks[t])}</td>`;
      }).join('')}
    </tr>`).join('')}</tbody>
  </table>`;
}

// Why the order in use is the one in use. learn.py only lets a richer order
// replace the plain prior when it is no worse on either task and better by
// more than luck on at least one (Holm-corrected over the two tasks); this
// reports each decision it made, with its numbers.
export function choiceNote(ranking) {
  const decisions = ranking?.choice ?? [];
  if (!decisions.length) return '';
  const what = {
    prior_fit: 'Adding interactions between a dataset\'s measured features and a model\'s family',
    prior_knn: 'Weighting each model toward what it did on the benchmark datasets nearest to yours',
  };
  const n = ranking.trained_on?.datasets;
  const lines = decisions.map(d => {
    const detail = Object.entries(d.tasks).map(([task, s]) =>
      `better on ${s.wins} and worse on ${s.losses} ${unitNoun(ranking.tasks?.[task], task)} (p = ${formatP(s.p_holm)})`).join(', ');
    return d.replaced
      ? `${what[d.candidate] ?? d.candidate} beat the plain per-model order by more than luck on ${n} datasets: ${detail}. It is the order in use.`
      : `${what[d.candidate] ?? d.candidate} was tried too: ${detail}. That is not better by more than luck, so it is off.`;
  });
  return `${lines.join(' ')} Which order ships is decided by a rule fixed before the results were seen, in bench/dcn/learn.py.`;
}

// One sentence on the comparison people actually ask about: is it better
// than just reaching for boosting?
export function boostingVerdict(ranking) {
  if (!ranking?.chosen || ranking.chosen === 'boosting') return '';
  const parts = [], beyond = [];
  for (const [task, entry] of Object.entries(ranking.tasks)) {
    const c = entry.against_chosen?.boosting;
    if (!c) continue;
    parts.push(`${c.wins} of ${c.wins + c.losses + c.ties} ${unitNoun(entry, task)} (p = ${formatP(c.p_holm)})`);
    if (beyondLuck(c)) beyond.push(task);
  }
  if (!parts.length) return '';
  const verdict = beyond.length === 0
    ? (parts.length > 1 ? 'Neither difference is more than luck on this many datasets.'
      : 'That is within what luck produces on this many datasets.')
    : beyond.length === parts.length
      ? (parts.length > 1 ? 'Both differences are more than luck.' : 'That is more than luck.')
      : `Only the ${beyond.join(' and ')} difference is more than luck${
        parts.length && Object.values(ranking.tasks).some(e => beyondLuck(e.against_chosen?.boosting) &&
          e.against_chosen.boosting.p_holm >= 0.01) ? ', and only narrowly' : ''}.`;
  return `Against always using boosting, the order in use was better on ${parts.join(' and ')}. ${verdict}`;
}

// Average rank of every model over the benchmark's independent units,
// recomputed from the scores on the page. A synthetic family (datasets
// generated from one function) is one unit, scored by each model's mean over
// its datasets, rounded to six decimals. A model that did not finish on a unit
// ranks last there, tied with any other that did not finish. Mirrors
// score_matrix() and average_ranks() in bench/dcn/significance.py, and the
// tests hold the two together.
export function averageRanks(datasets, task, models) {
  const totals = Object.fromEntries(models.map(m => [m, 0]));
  const units = new Map();
  for (const d of datasets.filter(x => x.task === task)) {
    const key = d.family ?? d.dataset;
    if (!units.has(key)) units.set(key, []);
    units.get(key).push(d);
  }
  const rows = [...units.values()].map(members => ({
    scores: Object.fromEntries(models.map(m => {
      const seen = members.map(d => d.scores?.[m]).filter(v => v != null);
      return [m, seen.length ? Math.round(seen.reduce((a, b) => a + b, 0) / seen.length * 1e6) / 1e6 : null];
    })),
  }));
  for (const d of rows) {
    const values = models.map(m => d.scores?.[m] ?? -Infinity);
    for (let i = 0; i < models.length; i++) {
      let above = 0, same = 0;
      for (let j = 0; j < models.length; j++) {
        if (values[j] > values[i]) above++;
        else if (values[j] === values[i]) same++;
      }
      totals[models[i]] += above + (same + 1) / 2;
    }
  }
  return Object.fromEntries(models.map(m => [m, rows.length ? totals[m] / rows.length : NaN]));
}

// Which models the benchmark can tell apart: every model's average rank on a
// shared axis, with the critical difference shaded from the best. A model
// whose dot falls in the band cannot be told apart from the best one on
// this many datasets. Built as rows rather than an SVG so it stays legible on
// a phone.
export function rankChart(block, names) {
  const entries = Object.entries(block.ranks);
  if (entries.length < 2) return '';
  const k = entries.length;
  const pos = (r) => Math.max(0, Math.min(100, ((r - 1) / (k - 1)) * 100));
  const best = entries[0][1];
  const cd = block.critical_difference;
  const bandLeft = pos(best);
  const bandWidth = pos(best + cd) - bandLeft;
  const tied = new Set(block.tied_with_best);
  const step = Math.max(1, Math.ceil(k / 8));
  const ticks = [];
  for (let r = 1; r <= k; r += step) ticks.push(r);

  return `<div class="cd" role="table" aria-label="average rank of every model, 1 is best">
    <div class="cd-row cd-axis" role="row">
      <div class="cd-label" role="columnheader">average rank, 1 is best</div>
      <div class="cd-track" aria-hidden="true">${ticks.map(r =>
        `<span class="cd-tick" style="left:${pos(r).toFixed(2)}%">${r}</span>`).join('')}</div>
      <div class="cd-val" role="columnheader">rank</div>
    </div>
    ${entries.map(([code, rank]) => {
      const inBand = tied.has(code);
      const name = names[code] ?? code;
      const tip = `${code} ${name}: average rank ${rank.toFixed(2)}, ` +
        (inBand ? 'within the critical difference of the best' : 'separated from the best');
      return `<div class="cd-row" role="row" title="${esc(tip)}">
        <div class="cd-label" role="cell">${code.startsWith('BASE-')
          ? `<span class="rec-code">${esc(code)}</span>`
          : `<span class="rec-code" data-model="${esc(code)}">${esc(code)}</span>`} ${esc(name)}</div>
        <div class="cd-track" aria-hidden="true">
          <span class="cd-band" style="left:${bandLeft.toFixed(2)}%;width:${bandWidth.toFixed(2)}%"></span>
          <span class="cd-dot ${inBand ? 'in' : 'out'}" style="left:${pos(rank).toFixed(2)}%"></span>
        </div>
        <div class="cd-val" role="cell">${rank.toFixed(2)}<span class="cd-state">${inBand ? 'tied' : 'behind'}</span></div>
      </div>`;
    }).join('')}
  </div>`;
}

// What the luck of one cross-validation split does, on the datasets that were
// run under several seeds.
export function seedsNote(seeds, metrics = {}) {
  const parts = Object.entries(seeds ?? {}).filter(([, s]) => s.datasets).map(([task, s]) => {
    const flips = s.compared
      ? ` The order in use's first pick and boosting swapped places between seeds on ${s.flips} of ${s.compared}.`
      : '';
    return `On ${s.datasets} ${task} datasets run under ${s.seeds} seeds, a model's score moved by a median of
      ${num(s.score_spread)}${metrics[task] ? ` ${metrics[task]}` : ''} from one split to another, and the best model was the
      same under every seed on ${pct(s.same_best)} of them.${flips}`;
  });
  if (!parts.length) return '';
  return `${parts.join(' ')} That is why every comparison above is made across datasets rather than within one, and why
    a single dataset's winner is weak evidence on its own.`;
}

function significanceSection(ev) {
  const blocks = ev.significance;
  if (!blocks) return '';
  return Object.entries(blocks).map(([task, block]) => {
    const f = block.friedman;
    const tiedCount = block.tied_with_best.length;
    const where = (block.units ?? block.datasets) < block.datasets
      ? `${block.datasets} ${task} datasets (${block.units} independent, each synthetic family counted once)`
      : `${block.datasets} ${task} datasets`;
    const lead = `On ${where} the models do differ (Friedman test, p = ${formatP(f.p)}).
      But two models need average ranks more than ${num(block.critical_difference, 2)} apart before the difference is more
      than luck (Nemenyi, α = ${block.alpha}), and ${tiedCount} of the ${f.models} are within that of the best one: the shaded
      band. More independent datasets narrow the band.`;
    return `<h3 class="ev-h">Which ${esc(task)} models can be told apart</h3>
      <p class="sect-note">${lead}</p>
      ${rankChart(block, block.names ?? {})}`;
  }).join('');
}

function modelTable(models) {
  const rows = [];
  for (const [code, model] of Object.entries(models)) {
    for (const [task, stats] of Object.entries(model.tasks)) {
      rows.push({ code, name: model.name, task, ...stats });
    }
  }
  rows.sort((a, b) => b.was_best - a.was_best || a.median_regret - b.median_regret);
  return `<table class="ev-table">
    <thead><tr><th>model</th><th>task</th><th>was best</th><th>shown first</th>
      <th>median regret</th><th>median seconds</th></tr></thead>
    <tbody>${rows.map(r => `<tr>
      <td><span class="rec-code" data-model="${esc(r.code)}">${esc(r.code)}</span> ${esc(r.name)}</td>
      <td>${esc(r.task)}</td>
      <td>${r.was_best} of ${r.datasets}</td>
      <td>${r.recommended_first}</td>
      <td>${num(r.median_regret)}</td>
      <td>${num(r.median_seconds, 2)}</td>
    </tr>`).join('')}</tbody>
  </table>`;
}

function datasetTable(datasets) {
  return `<table class="ev-table">
    <thead><tr><th>dataset</th><th>shape</th><th>signature</th>
      <th>best model</th><th>shown first</th><th>boosting</th></tr></thead>
    <tbody>${datasets.map(d => `<tr>
      <td>${esc(d.dataset)}<span class="ev-sub">${esc(d.task)}</span></td>
      <td>${d.rows} × ${d.features}</td>
      <td class="ev-sig">${d.signature.split(' ').map(c =>
        `<span class="chip" data-code="${esc(c)}">${esc(c)}</span>`).join('')}</td>
      <td><span class="rec-code" data-model="${esc(d.best.model)}">${esc(d.best.model)}</span> ${num(d.best.score)}</td>
      <td><span class="rec-code" data-model="${esc(d.first.model)}">${esc(d.first.model)}</span> ${num(d.first.score)}
        <span class="ev-sub">best of four ${num(d.top4)}</span></td>
      <td>${num(d.boosting)}</td>
    </tr>`).join('')}</tbody>
  </table>`;
}

export function buildEvidence(T) {
  const intro = document.getElementById('ev-intro');
  const body = document.getElementById('ev-body');
  const ev = T.EVIDENCE;

  if (!ev) {
    intro.textContent = 'No benchmark run is recorded in this copy.';
    body.innerHTML = '';
    return;
  }

  intro.innerHTML = `${esc(ev.how)} The datasets come from
    <a href="${esc(ev.source_url)}" target="_blank" rel="noopener noreferrer">${esc(ev.source)} &#8599;</a>:
    ${esc(ev.run)}. Lower regret is better, and zero means the choice was the best model available.`;

  const head = ev.headline;
  const classification = head.classification, regression = head.regression;
  const rankedBy = ev.ranked_by ?? 'counting matched coordinates';
  const worse = classification.first > classification.boosting && regression.first > regression.boosting;
  const verdict = `These are the numbers for the run as it happened, when models were ordered by ${esc(rankedBy)}. The four
    shown contained the best available choice ${pct(classification.top4_was_best)} of the time on classification, and the
    model shown first trailed the best by ${num(classification.first)} on classification and ${num(regression.first)} on
    regression${worse ? ', which is worse than reaching for boosting' : ''}. The next table is the fairer test of the order
    the site uses now, because every number in it is leave-one-dataset-out.`;

  body.innerHTML = `
    <h3 class="ev-h">How the advice did</h3>
    ${headlineTable(head)}
    <p class="sect-note" style="margin-top:18px">${verdict}</p>

    ${ev.ranking ? `<h3 class="ev-h">What the order is worth</h3>
    <p class="sect-note">The site used to show whichever model matched the most coordinates. It now shows them in the order
      they were worth on the benchmark. Every number here is leave-one-dataset-out: the dataset being ranked contributed
      nothing to the weights that rank it, so this is what the ranking does on data it has not seen.</p>
    ${rankingTable(ev.ranking)}
    <p class="sect-note" style="margin-top:14px">A median over a few dozen datasets moves when a few datasets change, so
      the order in use is also compared, dataset by dataset, with the two things it claims to beat, counting coordinates and
      always using default boosting, and with references it makes no claim to beat: boosting that was tuned, and TabPFN
      where it was run (Wilcoxon signed-rank test, Holm-corrected for the number of comparisons). Datasets generated from
      one function, like PMLB's Friedman and Strogatz families, are held out together and counted once: sisters share a
      winner, and counting each would claim more certainty than the data holds.
      ${esc([boostingVerdict(ev.ranking), referenceVerdict(ev.ranking, 'tuned', 'tuned boosting'),
        referenceVerdict(ev.ranking, 'tabpfn', 'TabPFN')].filter(Boolean).join(' '))}</p>
    ${comparisonTable(ev.ranking)}
    <p class="sect-note" style="margin-top:14px">${esc(choiceNote(ev.ranking))}</p>
    ${ceilingTable(ev.ranking) ? `<h3 class="ev-h">How far from the best of everything</h3>
    <p class="sect-note">Regret above is measured against the best taxonomy model that ran. This measures against the best of
      everything that ran, the tuned reference${Object.values(ev.ranking.tasks).some(e => e.ceiling?.tabpfn) ? ' and TabPFN' : ''}
      included: how much a strategy leaves on the table. Tuned boosting uses ${esc(ev.tuning ?? 'a small search')}.</p>
    ${ceilingTable(ev.ranking)}` : ''}` : ''}

    ${significanceSection(ev)}
    ${(() => { const metrics = Object.fromEntries(Object.entries(ev.headline ?? {}).map(([k, v]) => [k, v.metric]));
      const note = seedsNote(ev.seeds, metrics);
      return note ? `<h3 class="ev-h">How much is the luck of the split</h3><p class="sect-note">${esc(note)}</p>` : ''; })()}

    <h3 class="ev-h">Every model that ran</h3>
    <p class="sect-note">“Was best” counts datasets where this model scored highest of all that ran.
      “Shown first” counts datasets where the instrument put it at the top <em>during that run</em>, when models were
      ordered by ${esc(ev.ranked_by ?? 'counting matched coordinates')}.</p>
    ${modelTable(ev.models)}

    <h3 class="ev-h">Every dataset</h3>
    <p class="sect-note">${ev.datasets.length} datasets, ${ev.model_runs} model runs. Click any code to open its definition.</p>
    ${datasetTable(ev.datasets)}

    <h3 class="ev-h">What could not be tested</h3>
    <p class="sect-note">A CSV cannot hold an image, a graph or a sequence, so these models are in the reference
      but never in the benchmark:</p>
    <ul class="ruled">${Object.entries(ev.not_runnable).map(([code, why]) =>
      `<li><span class="rec-code" data-model="${esc(code)}">${esc(code)}</span> ${esc(why)}</li>`).join('')}</ul>`;
}
